CREATE TABLE users (
	first_name VARCHAR(50) NOT NULL, 
	last_name VARCHAR(50) NOT NULL, 
	email VARCHAR(120) NOT NULL, 
	password VARCHAR(128) NOT NULL, 
	is_admin BOOLEAN, 
	id VARCHAR(36) NOT NULL, 
	created_at DATETIME, 
	updated_at DATETIME, 
	PRIMARY KEY (id), 
	UNIQUE (email)
);
